import{_ as l,o as i,c as t,a2 as o}from"./chunks/framework.DpXDHk3d.js";const q=JSON.parse('{"title":"3.4 安全距离与安全防护","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-4-an-quan-ju-li-yu-an-quan-fang-hu.md","filePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-4-an-quan-ju-li-yu-an-quan-fang-hu.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-4-an-quan-ju-li-yu-an-quan-fang-hu.md"};function n(e,a,s,u,h,c){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="_3-4-安全距离与安全防护" tabindex="-1">3.4 安全距离与安全防护 <a class="header-anchor" href="#_3-4-安全距离与安全防护" aria-label="Permalink to &quot;3.4 安全距离与安全防护&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>触电防护讲究&quot;防患于未然&quot;。这一节讲两件事:一是<strong>安全距离</strong>(人和电保持多远才安全),二是<strong>安全防护的&quot;五道防线&quot;</strong>(绝缘、屏护、间距、接地接零、漏电保护)。后者是全书的安全主线,后面多章都会用到。</p><h2 id="一、安全距离" tabindex="-1">一、安全距离 <a class="header-anchor" href="#一、安全距离" aria-label="Permalink to &quot;一、安全距离&quot;">​</a></h2><p><strong>安全距离</strong>,指为了防止触电和短路,人体、设备与带电体之间必须保持的最小距离。</p><ul><li><strong>电压越高,需要的安全距离越大</strong>——这是基本原则;</li><li>常用参考值:在 <strong>10 kV 及以下</strong>设备上不停电检修时,人体与带电导体之间距离不得小于 <strong>0.7 m</strong>;</li><li>低压线路和设备安装时,带电部分与接地部分之间、不同相带电部分之间,要保证足够的<strong>电气间隙</strong>和<strong>爬电距离</strong>。</li></ul><blockquote><p>具体数值由电压等级和场所决定。作为低压电工,记住&quot;电压越高距离越大&quot;的原则,以及 0.7 m 这个常见参考值即可。</p></blockquote><h2 id="二、安全防护的五道防线" tabindex="-1">二、安全防护的五道防线 <a class="header-anchor" href="#二、安全防护的五道防线" aria-label="Permalink to &quot;二、安全防护的五道防线&quot;">​</a></h2><h3 id="第一道-绝缘防护" tabindex="-1">第一道:绝缘防护 <a class="header-anchor" href="#第一道-绝缘防护" aria-label="Permalink to &quot;第一道:绝缘防护&quot;">​</a></h3><p>用绝缘材料把带电部分包裹起来,使人不能直接接触。</p><ul><li>导线外皮、电器外壳、绝缘手套、绝缘鞋、绝缘垫等;</li><li>绝缘材料会<strong>老化、受潮、破损</strong>,要定期检查绝缘性能(用兆欧表测绝缘电阻,第 4 章讲)。</li></ul><h3 id="第二道-屏护防护" tabindex="-1">第二道:屏护防护 <a class="header-anchor" href="#第二道-屏护防护" aria-label="Permalink to &quot;第二道:屏护防护&quot;">​</a></h3><p>用<strong>遮栏、护网、护罩、箱(柜)外壳</strong>等,把带电体隔离开。</p><ul><li>遮栏、栅栏高度一般<strong>不小于 1.7 m</strong>,并挂警示牌;</li><li>高压设备周围设遮栏,防止人员误入危险区。</li></ul><h3 id="第三道-间距防护" tabindex="-1">第三道:间距防护 <a class="header-anchor" href="#第三道-间距防护" aria-label="Permalink to &quot;第三道:间距防护&quot;">​</a></h3><p>靠<strong>安全距离</strong>本身防护——带电体之间、带电体与接地体之间、带电体与人体之间留够距离,防止放电、短路和触电。</p><h3 id="第四道-接地-接零-防护" tabindex="-1">第四道:接地(接零)防护 <a class="header-anchor" href="#第四道-接地-接零-防护" aria-label="Permalink to &quot;第四道:接地(接零)防护&quot;">​</a></h3><p>把设备<strong>金属外壳</strong>可靠接地(或接零),一旦绝缘损坏漏电,外壳电位被&quot;钳住&quot;,人触摸时不会受到致命电压。</p><ul><li>对应第 11 章的保护接地、保护接零;</li><li>这是<strong>最广泛、最重要</strong>的一道防线。</li></ul><h3 id="第五道-漏电保护-残余电流保护" tabindex="-1">第五道:漏电保护(残余电流保护) <a class="header-anchor" href="#第五道-漏电保护-残余电流保护" aria-label="Permalink to &quot;第五道:漏电保护(残余电流保护)&quot;">​</a></h3><p>安装<strong>漏电保护器</strong>,设备漏电时自动切断电源,防止人身触电(第 5.8 节详讲)。</p><blockquote><p>💡 记忆:**&quot;绝缘→屏护→间距→接地→漏保&quot;**五道防线,一层不够再加一层。考试常考&quot;下列哪些属于安全防护措施&quot;。</p></blockquote><h2 id="三、作业中的安全间距要求-要点" tabindex="-1">三、作业中的安全间距要求(要点) <a class="header-anchor" href="#三、作业中的安全间距要求-要点" aria-label="Permalink to &quot;三、作业中的安全间距要求(要点)&quot;">​</a></h2><ul><li>低压带电作业:应设专人监护,使用绝缘工具,人体<strong>不得同时接触相线与零线</strong>;</li><li>检修前必须先<strong>停电、验电、挂接地线</strong>(第 13 章详细展开);</li><li>不准随意拉接临时线,临时线要有完善的防护和间距。</li></ul><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ 五道防线:绝缘、屏护、间距、接地(接零)、漏电保护。</li><li>✅ 10 kV 及以下不停电检修,人体与带电体距离不小于 0.7 m。</li><li>✅ 遮栏高度一般不小于 1.7 m。</li><li>✅ 电压越高,安全距离越大。</li><li>⚠️ 易混点:屏护(遮栏挡着)和间距(留距离)是不同的防护方式,别混。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>安全距离原则:电压越高距离越大。</li><li>五道防线层层设防:绝缘 → 屏护 → 间距 → 接地接零 → 漏电保护。</li><li>低压作业仍要遵守停电、验电、挂地线的基本规程。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(多选)下列属于电气安全防护措施的有()。 A. 绝缘　B. 屏护　C. 间距　D. 接地接零</li><li>(判断)10 kV 及以下设备不停电检修时,人体与带电体的安全距离不小于 0.7 m。( )</li><li>(单选)遮栏、栅栏的高度一般不小于()。 A. 0.7 m　B. 1.2 m　C. 1.7 m　D. 2.5 m</li><li>(判断)电压越高,人体与带电体之间需要的安全距离越大。( )</li><li>(单选)保护接地是防止()触电的有效措施。 A. 两相触电　B. 接触电压触电　C. 跨步电压触电　D. 单相触电</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>ABCD</strong>。绝缘、屏护、间距、接地接零、漏电保护都是安全防护措施。</li><li><strong>√</strong>。0.7 m 是常见参考值。</li><li><strong>C</strong>。遮栏高度一般不小于 1.7 m。</li><li><strong>√</strong>。电压越高,越需要更大的安全距离。</li><li><strong>B</strong>。设备外壳接地可防止接触电压触电(漏电外壳带电时)。</li></ol></details>',31)])])}const g=l(r,[["render",n]]);export{q as __pageData,g as default};
